package com.bookstore.config;
import com.bookstore.entity.*; import com.bookstore.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class DataSeeder { @Bean CommandLineRunner seed(UserRepository users,BookRepository books,PasswordEncoder enc){return args->{if(users.count()==0){users.save(new User("admin",enc.encode("admin123"),"admin@bookstore.local",Role.ADMIN));users.save(new User("user",enc.encode("user123"),"user@bookstore.local",Role.USER));} if(books.count()==0){books.save(new Book("Clean Code","Robert C. Martin","Programming","A practical guide to writing clean and maintainable code.",650,10,""));books.save(new Book("Effective Java","Joshua Bloch","Programming","Best practices for modern Java development.",800,8,""));books.save(new Book("The Alchemist","Paulo Coelho","Fiction","A classic inspirational novel.",350,15,""));}};}}
